// src/commands/ctx-aug.ts
function registerCtxAugCommand(pi, config) {
  const runner = new PiSubagentRunner;
  pi.registerCommand("ctx-aug", {
    description: "Augment your prompt with relevant project context (sidekick)",
    handler: async (args, ctx) => {
      const prompt = args.trim();
      const branch = ctx.sessionManager.getBranch();
      const lastEntryId = branch.length > 0 ? branch[branch.length - 1]?.id : "unknown";
      const sessionLabel = `pi-session-${lastEntryId}`;
      const currentConfig = typeof config === "function" ? config(ctx) : config;
      if (!currentConfig) {
        ctx.ui.notify("/ctx-aug: Sidekick is not configured. Add `sidekick.model` to your magic-context.jsonc to enable this command.", "warning");
        return;
      }
      if (prompt.length === 0) {
        ctx.ui.notify("/ctx-aug: Usage `/ctx-aug <your prompt>` — provide a prompt to augment with project memory context.", "info");
        return;
      }
      if (ctx.hasUI) {
        ctx.ui.notify("\uD83D\uDD0D Preparing augmentation… 2-10s depending on your sidekick provider.", "info");
      }
      sessionLog(sessionLabel, "/ctx-aug: spawning sidekick", {
        model: currentConfig.model
      });
      const projectIdentity = resolveProjectIdentity(ctx.cwd);
      sessionLog(sessionLabel, "/ctx-aug: project identity", projectIdentity);
      const result = await runner.run({
        agent: "sidekick",
        systemPrompt: withContentLanguageDirective(currentConfig.systemPrompt ?? SIDEKICK_SYSTEM_PROMPT, currentConfig.language),
        userMessage: prompt,
        model: currentConfig.model,
        fallbackModels: currentConfig.fallbackModels,
        timeoutMs: currentConfig.timeoutMs ?? 30000,
        cwd: ctx.cwd,
        signal: ctx.signal,
        thinkingLevel: currentConfig.thinking_level,
        accountingSessionId: sessionLabel,
        accountingSubagent: "sidekick"
      });
      if (!result.ok) {
        log(`[magic-context][omp] /ctx-aug: sidekick failed (${result.reason}): ${result.error}`);
        if (ctx.hasUI) {
          ctx.ui.notify(`/ctx-aug: sidekick failed (${result.reason}). Sending prompt without augmentation.`, "warning");
        }
        pi.sendUserMessage(prompt);
        return;
      }
      const sidekickText = stripThinkingBlocks(result.assistantText);
      sessionLog(sessionLabel, `/ctx-aug: sidekick returned ${sidekickText.length} chars in ${result.durationMs}ms`);
      if (isEmptySidekickResult(sidekickText)) {
        pi.sendUserMessage(prompt);
        return;
      }
      const augmentedPrompt = `${prompt}

<sidekick-augmentation>
${sidekickText}
</sidekick-augmentation>`;
      pi.sendUserMessage(augmentedPrompt);
    }
  });
}

