    ensureRegistered: ensureProjectRegisteredFromPiDirectory,
    retrospectiveRawProvider: () => new PiRetrospectiveRawProvider({ projectCwd: opts.projectDir }),
    primerRawProviderFactory: createPiPrimerRawProviderFactory()
