// src/pi-recomp-client-shared.ts
function createPiHistorianClient(args) {
  const sessions = new Map;
  let counter = 0;
  async function prompt(input) {
    const body = readBody(input);
    const sessionId = readPathId(input);
    if (body.noReply) {
      const text = extractPromptText(body.parts);
      if (text.length > 0)
        args.notify(text);
      return {};
    }
    const promptText = extractPromptText(body.parts);
    const modelOverride = readBodyModel(body);
    const result = await args.runner.run({
      agent: "magic-context-historian",
      systemPrompt: args.systemPrompt,
      userMessage: promptText,
      model: modelOverride ?? args.model,
      fallbackModels: modelOverride ? undefined : args.fallbackModels,
      timeoutMs: args.timeoutMs,
      cwd: args.directory,
      thinkingLevel: args.thinkingLevel,
      accountingSessionId: args.accountingSessionId,
      accountingSubagent: "recomp"
    });
    if (!result.ok) {
      throw new Error(`Pi recomp historian failed (${result.reason}): ${result.error}`);
    }
    sessions.set(sessionId, [makeMessage2("assistant", result.assistantText)]);
    return {};
  }
  return {
    session: {
      get: async () => ({ directory: args.directory }),
      create: async () => {
        const id = `magic-context-pi-recomp-${++counter}`;
        sessions.set(id, []);
        return { id };
      },
      prompt,
      promptAsync: prompt,
      messages: async (input) => ({
        data: sessions.get(readPathId(input)) ?? []
      }),
      delete: async (input) => {
        sessions.delete(readPathId(input));
        return {};
      }
    }
  };
}
function readPathId(input) {
  if (typeof input !== "object" || input === null)
    return "";
  const path11 = input.path;
  return typeof path11?.id === "string" ? path11.id : "";
}
function readBody(input) {
  if (typeof input !== "object" || input === null)
    return {};
  const body = input.body;
  return typeof body === "object" && body !== null ? body : {};
}
function readBodyModel(body) {
  const model = body.model;
  if (typeof model !== "object" || model === null)
    return;
  const { providerID, modelID } = model;
  if (typeof providerID === "string" && providerID.length > 0 && typeof modelID === "string" && modelID.length > 0) {
    return `${providerID}/${modelID}`;
  }
  return;
}
function extractPromptText(parts) {
  if (!Array.isArray(parts))
    return "";
  return parts.map((part) => typeof part === "object" && part !== null ? part.text : undefined).filter((text) => typeof text === "string" && text.length > 0).join(`
`);
}
function makeMessage2(role, text) {
  return {
    info: { role, time: { created: Date.now() } },
    parts: [{ type: "text", text }],
    role,
    content: [{ type: "text", text }]
  };
}

// src/pi-recomp-marker.ts
function stagePiRecompMarker(args) {
  const readBranchEntries = resolvePiReadBranchEntries2(args.ctx);
  if (!readBranchEntries)
    return;
  const compartments = getCompartments(args.db, args.sessionId);
  const last = compartments[compartments.length - 1];
  if (!last)
    return;
  let firstKeptEntryId = null;
  try {
    firstKeptEntryId = findFirstKeptEntryId(readBranchEntries(), last.endMessage);
  } catch {
    firstKeptEntryId = null;
  }
  if (!firstKeptEntryId || last.endMessageId.length === 0)
    return;
  setPendingPiCompactionMarkerState(args.db, args.sessionId, {
    firstKeptEntryId,
    endMessageId: last.endMessageId,
    ordinal: last.endMessage,
    tokensBefore: 0,
    summary: buildPiCompactionSummary(compartments),
    publishedAt: Date.now()
  });
  signalPiDeferredHistoryRefresh(args.sessionId);
}
function resolvePiReadBranchEntries2(ctx) {
  const sm = ctx?.sessionManager;
  if (typeof sm?.getBranch !== "function")
    return;
  return () => {
    try {
      const entries = sm.getBranch?.call(sm);
      return Array.isArray(entries) ? entries : [];
    } catch {
      return [];
    }
  };
}

