    return "today";
  if (days === 1)
    return "1d ago";
  if (days < 30)
    return `${days}d ago`;
  const months = Math.floor(days / 30);
  if (months === 1)
    return "1mo ago";
  if (months < 12)
    return `${months}mo ago`;
  const years = Math.floor(days / 365);
